        } else if (type instanceof Float) {
            stackMapTableEntries.add(new StackMapTableEntry.FloatType((Float) type));
        } else if (type instanceof Long) {
            stackMapTableEntries.add(new StackMapTableEntry.LongType((Long) type));
        } else if (type instanceof Double) {
            stackMapTableEntries.add(new StackMapTableEntry.DoubleType((Double) type));
        } else if (type instanceof NullType) {
            stackMapTableEntries.add(new StackMapTableEntry.NullType());
