public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        return putNullBytes(byteLength);
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byteOffset: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("Invalid byteLength: " + byteLength);
    }
    ensureCapacity(byteLength);
    System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
    length += byteLength;
    return this;
}

