public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 11) {
        return 11;
    }
    if (desiredCapacity < 1000) {
        return (int) (desiredCapacity / 0.9);
    }
    int prime = (int) (desiredCapacity / 0.9);
    while (!isPrime(prime)) {
        prime++;
    }
    return prime;
}

