        return 0;
    }
    int tag = readRawVarint32();
    if (tag >>> TAG_TYPE_BITS == 0) {
        // If we actually read zero, that's not a valid tag.
        throw InvalidProtocolBufferException.invalidTag();
    }
    return tag;
}

